"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1994],{44770:e=>{e.exports=JSON.parse('{"functions":[{"name":"InviteFriends","desc":"Opens Roblox\'s invite prompt for the local player.\\n\\nYields while checking `SocialService:CanSendGameInviteAsync()` and returns\\nwith a `warn` \u2014 but no prompt and no error \u2014 when the player is not eligible\\nto invite (Studio commonly refuses game invites outright, so a `cannot\\ninvite` warn there is expected, not a bug). There is no return value or\\ncallback, so the caller cannot tell whether an invite was actually sent;\\nlisten to [SocialService.GameInvitePromptClosed] if you need that.\\n\\nThe prompt carries launch data containing the sender\'s `UserId`, which the joining\\nplayer\'s client can read back to attribute the referral.","params":[],"returns":[],"function_type":"static","realm":["Client"],"source":{"line":31,"path":"src/Shared/Modules/InviteFriends.luau"}}],"properties":[],"types":[],"name":"InviteFriends","desc":"Quick function to invite a local player\'s friends to the game.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":9,"path":"src/Shared/Modules/InviteFriends.luau"}}')}}]);